import pandas as pd
from collections import Counter, defaultdict
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Prefix-oriented row/column permutation optimizer with prototype alignment."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the input reference and lightweight shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one scalar exactly as scoring does, mapping missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the common-prefix length using bounded binary-search slicing."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0
        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse as LCPs of adjacent sorted row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        prev = ordered[0]
        for cur in ordered[1:]:
            if cur == prev:
                total += len(cur)
            else:
                total += cls._lcp(prev, cur)
            prev = cur
        return total

    @staticmethod
    def _merged_units(columns, order, col_merge):
        """Return ordered atomic units, keeping every requested merge contiguous."""
        position = {c: i for i, c in enumerate(order)}
        claimed = set()
        units = []

        for request in col_merge or []:
            members = [c for c in order if c in request and c not in claimed]
            if members:
                members.sort(key=position.__getitem__)
                units.append(members)
                claimed.update(members)

        for c in order:
            if c not in claimed:
                units.append([c])

        units.sort(key=lambda unit: min(position[c] for c in unit))
        return units

    @classmethod
    def _apply_units(cls, columns, unit_order, col_merge):
        """Expand a unit order into source-column indices while honoring merges."""
        names = []
        for unit in unit_order:
            names.extend(unit)
        lookup = {c: j for j, c in enumerate(columns)}
        return [lookup[c] for c in names]

    @staticmethod
    def _serial(text, orders):
        """Build one scoring string per row from its row-specific column order."""
        return [
            "".join(text[r][j] for j in orders[r])
            for r in range(len(orders))
        ]

    def _global_order(self, text, columns, col_merge):
        """Rank columns by length-weighted repeated-value mass."""
        n, m = len(text), len(columns)
        stats = []
        for j in range(m):
            counts = Counter(text[r][j] for r in range(n))
            pair_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat_mass = sum(
                len(value) * (count - 1)
                for value, count in counts.items()
            )
            stats.append((pair_mass, repeat_mass, len(counts), j))

        ranked = sorted(
            range(m),
            key=lambda j: (
                -stats[j][0], -stats[j][1], stats[j][2], j
            ),
        )
        names = [columns[j] for j in ranked]
        units = self._merged_units(columns, names, col_merge)
        return units, ranked, stats

    def _conditional(self, text, columns, col_merge, ranked, stats):
        """Construct bounded conditional prefix groups using repeated field values."""
        n, m = len(text), len(columns)
        result = [None] * n
        candidates = [
            j for j in ranked if stats[j][0] > 0
        ][:min(16, m)]
        max_depth = min(6, len(candidates))
        node_limit = 192
        nodes = 0

        def finish(rows, prefix, remaining):
            ordered = prefix + [j for j in ranked if j in remaining]
            units = self._merged_units(
                columns, [columns[j] for j in ordered], col_merge
            )
            order = self._apply_units(columns, units, col_merge)
            for r in rows:
                result[r] = order[:]

        def visit(rows, remaining, prefix, depth):
            nonlocal nodes
            nodes += 1
            available = [j for j in candidates if j in remaining]
            if (
                len(rows) < 2
                or not available
                or depth >= max_depth
                or nodes > node_limit
            ):
                finish(rows, prefix, remaining)
                return

            best = None
            for j in available:
                groups = defaultdict(list)
                for r in rows:
                    groups[text[r][j]].append(r)
                score = sum(
                    len(value) * len(group) * (len(group) - 1)
                    for value, group in groups.items()
                    if len(group) > 1
                )
                key = (score, -j)
                if best is None or key > best[0]:
                    best = (key, j, groups)

            if best is None or best[0][0] <= 0:
                finish(rows, prefix, remaining)
                return

            j, groups = best[1], best[2]
            rest = [x for x in remaining if x != j]
            ordered_groups = sorted(
                groups.values(), key=lambda group: (-len(group), min(group))
            )
            for group in ordered_groups:
                visit(group, rest, prefix + [j], depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)
        fallback_units = self._merged_units(
            columns, [columns[j] for j in ranked], col_merge
        )
        fallback = self._apply_units(columns, fallback_units, col_merge)
        return [x if x is not None else fallback[:] for x in result]

    def _prototype_alignment(
        self, text, columns, col_merge, ranked, stats
    ):
        """Align rows to lexicographic group prototypes using partial-prefix LCPs."""
        n, m = len(text), len(columns)
        global_units = self._merged_units(
            columns, [columns[j] for j in ranked], col_merge
        )

        # Treat merged groups as indivisible atomic blocks.
        lookup = {c: j for j, c in enumerate(columns)}
        blocks = [[lookup[c] for c in unit] for unit in global_units]
        block_text = [
            ["".join(text[r][j] for j in block) for block in blocks]
            for r in range(n)
        ]
        bcount = len(blocks)

        masses = []
        for b in range(bcount):
            counts = Counter(block_text[r][b] for r in range(n))
            mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            masses.append((mass, -b))
        anchor_blocks = [
            b for _, b in sorted(masses, reverse=True)[:12]
            if masses[b][0] > 0
        ]

        # Choose the strongest repeated anchor, with a deterministic cap.
        groups = {}
        if anchor_blocks:
            anchor = anchor_blocks[0]
            for r in range(n):
                groups.setdefault(block_text[r][anchor], []).append(r)
        else:
            groups = {"": list(range(n))}

        group_items = sorted(
            groups.values(), key=lambda rows: (-len(rows), min(rows))
        )[:128]

        result = [None] * n
        base_block_order = list(range(bcount))

        for rows in group_items:
            prototype = min(
                rows,
                key=lambda r: "".join(block_text[r][b] for b in base_block_order),
            )
            proto_order = base_block_order[:]
            proto_string = "".join(block_text[prototype][b] for b in proto_order)

            # The prototype itself uses the global target order.
            result[prototype] = [
                j for b in proto_order for j in blocks[b]
            ]

            for r in rows:
                if r == prototype:
                    continue

                available = set(base_block_order)
                chosen = []
                suffix_pos = 0
                aligned = True

                while available:
                    remaining_suffix = proto_string[suffix_pos:]
                    choices = list(available)
                    if len(choices) > 16:
                        choices.sort(
                            key=lambda b: (
                                -masses[b][0], b
                            )
                        )
                        choices = choices[:16]

                    best = None
                    for b in choices:
                        value = block_text[r][b]
                        gain = self._lcp(value, remaining_suffix)
                        key = (gain, masses[b][0], -b)
                        if best is None or key > best[0]:
                            best = (key, b, value)

                    b = best[1]
                    value = best[2]
                    chosen.append(b)
                    available.remove(b)

                    gain = best[0][0]
                    if aligned and gain == len(value):
                        suffix_pos += len(value)
                    else:
                        aligned = False
                        # Once the target no longer matches, finish cheaply
                        # with the unused global tail.
                        chosen.extend(
                            b2 for b2 in base_block_order if b2 in available
                        )
                        break

                result[r] = [j for b in chosen for j in blocks[b]]

        fallback = [
            j for b in base_block_order for j in blocks[b]
        ]
        return [order if order is not None else fallback[:] for order in result]

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate global, conditional, and prototype-aligned permutations."""
        self.df = df
        self.num_rows, self.num_cols = df.shape
        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[r, j]) for j in range(m)]
            for r in range(n)
        ]

        units, ranked, stats = self._global_order(
            text, columns, col_merge
        )
        global_order = self._apply_units(columns, units, col_merge)
        global_orders = [global_order[:] for _ in range(n)]

        conditional_orders = self._conditional(
            text, columns, col_merge, ranked, stats
        )
        prototype_orders = self._prototype_alignment(
            text, columns, col_merge, ranked, stats
        )

        candidates = []
        for orders in (global_orders, conditional_orders, prototype_orders):
            serial = self._serial(text, orders)
            candidates.append((self._reuse(serial), orders, serial))

        _, best_orders, best_serial = max(
            candidates, key=lambda item: item[0]
        )
        row_order = sorted(range(n), key=lambda r: best_serial[r])

        output = [
            [raw[r, j] for j in best_orders[r]]
            for r in row_order
        ]
        orderings = [
            [columns[j] for j in best_orders[r]]
            for r in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

